# Compare our filled file vs golden: check formatting & all non-formula values match
import openpyxl

def dump(path):
    wb = openpyxl.load_workbook(path, data_only=False)
    ws = wb['Sheet1']
    out = {}
    for row in ws.iter_rows(min_row=1, max_row=9, min_col=1, max_col=21):
        for c in row:
            out[c.coordinate] = c.value
    return out

ours = dump('1_50573_answer_template_2293_input_filled.xlsx')
gold = dump('golden.xlsx')
for coord in sorted(set(gold)|set(ours)):
    g = gold.get(coord)
    o = ours.get(coord)
    if g != o:
        print('DIFF', coord, 'gold=', repr(g), 'ours=', repr(o))
print('done diff')
EOF
